-- SOLO LECTURA. Ejecutar después de las tres migraciones y comparar con pre.sql.
-- Devuelve conteos, firmas y huellas; nunca contenido ni IDs de usuarios/contratos.
-- Un cambio concurrente legítimo puede cambiar conteos: revisar antes de atribuirlo a la migración.
with expected_functions(name) as (
 values ('diime_cerrar_cancelacion'),('diime_reclamar_liquidacion'),('diime_finalizar_liquidacion'),('proteger_reparto_escrow'),
 ('diime_gestionar_solicitud_cancelacion'),('diime_abrir_disputa'),('empresa_puede_operar_trabajo'),('empresa_chat_parte'),
 ('empresa_tiene_permiso'),('empresa_es_administrador'),('validar_actor_trabajo_empresa'),('validar_actor_cobros_empresa'),('parte_cancelacion'),
 ('cerrar_cancelacion_aceptada'),('diime_autorizar_reintento_reembolso'),('diime_registrar_estado_reembolso'),
 ('notas_trabajos_proveedor'),('actualizar_planificacion_trabajo'),('validar_resena_trabajo'),('vincular_y_recalcular_resena'),
 ('crear_resena_trabajo'),('proteger_reputacion_profesional'),('validar_portfolio_trabajo'),('trabajos_valorables_profesional'),
 ('archivo_solicitud_acceso'),('archivo_oferta_acceso'),('archivo_url_acceso'),('archivo_puede_leer'),('archivo_privado_metadata'),
 ('validar_vinculos_archivos_privados'),('validar_adjuntos_actor'),('migrar_referencia_archivo_privado')
), attachment_references(parent,url) as (
 select 'solicitudes',v from public.solicitudes s cross join lateral jsonb_array_elements_text(case when jsonb_typeof(s.archivos)='array' then s.archivos else '[]'::jsonb end) v
 union all select 'ofertas',v from public.ofertas o cross join lateral jsonb_array_elements_text(case when jsonb_typeof(o.archivos)='array' then o.archivos else '[]'::jsonb end) v
 union all select 'trabajos',v from public.trabajos t cross join lateral jsonb_array_elements_text(case when jsonb_typeof(t.archivos)='array' then t.archivos else '[]'::jsonb end) v
 union all select 'cancelacion_solicitante',unnest(t.cancelacion_adjuntos_solicitante) from public.trabajos t
 union all select 'cancelacion_respuesta',unnest(t.cancelacion_adjuntos_respuesta) from public.trabajos t
 union all select 'actualizaciones',unnest(u.archivos) from public.actualizaciones_trabajo u
 union all select 'mensajes',m.archivo_url from public.mensajes m where m.archivo_url is not null
 union all select 'empresa_mensajes',m.archivo_url from public.empresa_mensajes m where m.archivo_url is not null
)
select jsonb_build_object(
 'observed_at',now(),
 'counts',jsonb_build_object('trabajos',(select count(*) from public.trabajos),'solicitudes',(select count(*) from public.solicitudes),'ofertas',(select count(*) from public.ofertas),'reviews',(select count(*) from public."reseñas"),'portfolio',(select count(*) from public.portfolio)),
 'notes_after',(select jsonb_build_object('rows',count(*),'bytes',coalesce(sum(octet_length(notas)),0),'digest',md5(coalesce(string_agg(trabajo_id::text||':'||md5(notas),E'\n' order by trabajo_id),''))) from diime_private.notas_trabajo_proveedor),
 'notes_shared_nonnull',(select count(*) from public.trabajos where notas_privadas_proveedor is not null),
 'notes_constraint',(select jsonb_build_object('validated',convalidated,'definition',pg_get_constraintdef(oid)) from pg_constraint where conrelid='public.trabajos'::regclass and conname='trabajos_notas_solo_privadas'),
 'private_tables',(select jsonb_agg(jsonb_build_object('table',c.oid::regclass::text,'rls',c.relrowsecurity,'anon_select',has_table_privilege('anon',c.oid,'select'),'authenticated_select',has_table_privilege('authenticated',c.oid,'select'),'authenticated_insert',has_table_privilege('authenticated',c.oid,'insert'),'authenticated_update',has_table_privilege('authenticated',c.oid,'update'),'authenticated_delete',has_table_privilege('authenticated',c.oid,'delete')) order by c.oid::regclass::text) from pg_class c where c.oid=any(array['diime_private.notas_trabajo_proveedor'::regclass,'diime_private.reintentos_reembolso'::regclass,'public.archivos_privados'::regclass])),
 'review_version_default',(select pg_get_expr(d.adbin,d.adrelid) from pg_attribute a join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid='public."reseñas"'::regclass and a.attname='integridad_version'),
 'review_unique_index',(select jsonb_build_object('valid',i.indisvalid,'ready',i.indisready,'unique',i.indisunique,'predicate',pg_get_expr(i.indpred,i.indrelid),'definition',pg_get_indexdef(i.indexrelid)) from pg_index i where i.indexrelid='public.resena_nueva_unica_por_trabajo'::regclass),
 'review_anomalies',jsonb_build_object('historical_rows',(select count(*) from public."reseñas" where integridad_version is null),'version2_rows',(select count(*) from public."reseñas" where integridad_version=2),'duplicate_contract_groups',(select count(*) from(select trabajo_id from public."reseñas" group by trabajo_id having count(*)>1)d),'wrong_provider',(select count(*) from public."reseñas" r join public.trabajos t on t.id=r.trabajo_id where r.profesional_id is distinct from t.profesional_id),'not_completed',(select count(*) from public."reseñas" r join public.trabajos t on t.id=r.trabajo_id where t.estado is distinct from 'completado'),'wrong_link',(select count(*) from public."reseñas" r join public.trabajos t on t.id=r.trabajo_id where t.review_cliente_id is distinct from r.id),'new_integrity_violations',(select count(*) from public."reseñas" r join public.trabajos t on t.id=r.trabajo_id where r.integridad_version=2 and (r.profesional_id is distinct from t.profesional_id or t.review_cliente_id is distinct from r.id or t.estado is distinct from 'completado'))),
 'portfolio_anomalies',jsonb_build_object('wrong_provider',(select count(*) from public.portfolio p join public.trabajos t on t.id=p.trabajo_id where p.profesional_id is distinct from t.profesional_id),'not_completed',(select count(*) from public.portfolio p join public.trabajos t on t.id=p.trabajo_id where t.estado is distinct from 'completado')),
 'triggers',(select jsonb_agg(jsonb_build_object('table',tgrelid::regclass::text,'name',tgname,'enabled',tgenabled,'definition',pg_get_triggerdef(oid)) order by tgname) from pg_trigger where not tgisinternal and tgname=any(array['validar_resena_trabajo','vincular_y_recalcular_resena','proteger_reputacion_profesional','validar_portfolio_trabajo','validar_archivos_solicitud','validar_archivos_oferta','validar_archivos_trabajo','validar_archivos_actualizacion','validar_archivos_mensaje','validar_archivos_mensaje_empresa'])),
 'functions',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition_hash',md5(pg_get_functiondef(p.oid)),'security_definer',p.prosecdef,'search_path',p.proconfig,'anon_execute',has_function_privilege('anon',p.oid,'execute'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'execute'),'service_execute',has_function_privilege('service_role',p.oid,'execute')) order by p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','diime_private') and p.proname in(select name from expected_functions)),
 'files',jsonb_build_object('bucket',(select jsonb_build_object('public',public,'limit',file_size_limit) from storage.buckets where id='adjuntos-privados'),'storage_policy',(select jsonb_build_object('permissive',polpermissive,'using',pg_get_expr(polqual,polrelid),'check',pg_get_expr(polwithcheck,polrelid)) from pg_policy where polrelid='storage.objects'::regclass and polname='adjuntos_privados_solo_servidor'),'metadata_rows',(select count(*) from public.archivos_privados),'legacy_rows',(select count(*) from public.archivos_privados where legacy_url is not null),'legacy_without_hash',(select count(*) from public.archivos_privados where legacy_url is not null and sha256 is null),'legacy_unshared',(select count(*) from public.archivos_privados where legacy_url is not null and not compartido),'legacy_private_references_remaining',(select count(*) from attachment_references r join public.archivos_privados a on a.legacy_url=r.url),'route_references_without_metadata',(select count(*) from attachment_references r where r.url like '%/api/archivos/%' and not exists(select 1 from public.archivos_privados a where a.url=r.url)),'blob_reference_counts',(select jsonb_object_agg(parent,n) from(select parent,count(*) n from attachment_references where url~'^https://[^/]+[.]public[.]blob[.]vercel-storage[.]com/' group by parent)x))
) as verification;
